<script setup>
import {ref,watch,nextTick,onBeforeUnmount,useId} from 'vue';
const props=defineProps({open:Boolean,title:String,step:{type:Number,default:0},steps:Array,busy:Boolean});
const emit=defineEmits(['close']);const dialog=ref(null),heading=ref(null),id=useId();let previous=null,overflow=null;
function restore(){if(overflow!==null){document.body.style.overflow=overflow;overflow=null;}if(previous?.isConnected)previous.focus();previous=null;}
watch(()=>props.open,async value=>{await nextTick();if(value&&props.open&&dialog.value&&!dialog.value.open){previous=document.activeElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.value.showModal();heading.value?.focus();}else if(!props.open){dialog.value?.close();restore();}},{immediate:true});
watch(()=>props.step,async()=>{await nextTick();heading.value?.focus();dialog.value?.querySelector('.getting-content')?.scrollTo(0,0);});
onBeforeUnmount(()=>{dialog.value?.close();restore();});
</script>
<template><Teleport to="body"><dialog ref="dialog" class="getting-dialog" :aria-labelledby="id" :aria-busy="busy" @cancel.prevent="!busy&&emit('close')"><header><div><p class="getting-kicker">AADI · GETTING STARTED</p><h2 :id="id" ref="heading" tabindex="-1">{{ title }}</h2></div><button type="button" class="getting-close" aria-label="Close getting started" :disabled="busy" @click="emit('close')">×</button></header><nav v-if="steps?.length" aria-label="Progress"><ol><li v-for="(label,index) in steps" :key="label" :class="{active:index===step,done:index<step}" :aria-current="index===step?'step':undefined"><span>{{ index+1 }}</span>{{ label }}</li></ol><p class="sr-only">Step {{ step+1 }} of {{ steps.length }}</p></nav><div class="getting-content"><slot /></div></dialog></Teleport></template>
<style>
.getting-dialog{margin:auto;width:min(640px,calc(100% - 24px));max-height:calc(100dvh - 32px - env(safe-area-inset-top,0px) - env(safe-area-inset-bottom,0px));padding:0;border:1px solid #c4ecea;border-radius:22px;background:#fff;color:#103e3b;box-shadow:0 24px 80px #06282733;overflow:auto}.getting-dialog::backdrop{background:#06282799}.getting-dialog>header{padding:24px 24px 16px;display:flex;align-items:start;gap:16px;justify-content:space-between}.getting-kicker{font-size:10px;letter-spacing:.14em;font-weight:800;color:#137671;margin:0 0 8px}.getting-dialog h2{font-size:25px;line-height:1.2;font-weight:750;margin:0}.getting-close{font-size:26px;min-width:44px;min-height:44px;border-radius:50%;border:1px solid #dbe9e6;background:white}.getting-dialog nav{padding:0 24px 16px;border-bottom:1px solid #e3eeeb}.getting-dialog ol{display:flex;gap:12px;list-style:none;padding:0;margin:0}.getting-dialog nav li{display:flex;align-items:center;gap:6px;font-size:11px;color:#627570}.getting-dialog nav li span{display:grid;place-items:center;width:24px;height:24px;border:1px solid #dbe9e6;border-radius:50%;flex:none}.getting-dialog nav .active{color:#103e3b;font-weight:750}.getting-dialog nav .active span{background:#f6ca52;border-color:#f6ca52}.getting-dialog nav .done span{background:#e3f6f4;color:#137671}.getting-content{padding:24px}.getting-content form,.getting-fields{display:grid;gap:18px}.getting-content p{font-size:14px;line-height:1.6;color:#526764;margin:0}.getting-content h3{font-size:17px;font-weight:750;margin:0 0 6px}.getting-content label{display:grid;gap:7px;font-size:13px;font-weight:650}.getting-content input:not([type=checkbox]),.getting-content select,.getting-content textarea{width:100%;min-height:44px;border:1px solid #cbded9;border-radius:9px;padding:10px 12px;background:white;color:#103e3b;font-size:16px}.getting-content .getting-check{display:flex;align-items:center;gap:10px;min-height:48px;border:1px solid #dbe9e6;border-radius:10px;padding:12px}.getting-check:has(input:checked){border-color:#137671;background:#eff9f7}.getting-check input{width:18px;height:18px;accent-color:#137671;flex:none}.getting-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.getting-actions{display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid #e3eeeb;padding-top:18px;margin-top:6px}.getting-content button,.getting-content .getting-link{min-height:44px;border:1px solid #cbded9;border-radius:9px;padding:10px 15px;font-size:13px;font-weight:700;background:white;cursor:pointer}.getting-content .getting-primary{background:#137671;color:white;border-color:#137671;margin-left:auto}.getting-content button:active{transform:scale(.98)}.getting-content button:disabled{opacity:.6;cursor:wait}.getting-dialog :focus-visible{outline:3px solid #e5b329;outline-offset:3px}.getting-dialog h2:focus{outline:none}.getting-errors{color:#b42318;background:#fff3ef;border-radius:10px;padding:12px;font-size:13px}.getting-content dl{display:grid;gap:5px;font-size:14px;margin:0}.getting-content dt{font-weight:700;margin-top:8px}.getting-content dd{margin:0;color:#526764;overflow-wrap:anywhere}.getting-file{border:1px solid #dbe9e6;border-radius:12px;padding:14px;display:grid;gap:12px;overflow-wrap:anywhere}.getting-content a{color:#137671;text-decoration:underline}.getting-note{padding:12px;border-left:3px solid #f6ca52;background:#fffcf0}
@media(max-width:480px){.getting-dialog>header{padding:20px 18px 14px}.getting-dialog h2{font-size:22px}.getting-dialog nav{padding:0 18px 14px}.getting-dialog ol{gap:8px;flex-wrap:wrap}.getting-content{padding:18px}.getting-grid{grid-template-columns:1fr}.getting-actions button{flex:1}.getting-content .getting-primary{margin-left:0}}
</style>
